INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51811, 'Daniel 6:10', 'Daniel', 6, 10, 'خو کله چې دانيال په دې خبر شو چې دا فرمان جارى شوے دے، نو هغه په خپل کور کښې بره کوټې ته لاړو چې کړکۍ يې د يروشلم طرف ته کولاو وې. نو هره ورځ به يې درې ځله سجده او دُعا کوله، او د خپل خُدائ پاک شُکر به يې ادا کولو، لکه څنګه چې هغۀ وړاندې کول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_10.mp3', '', 1761754199, 1761754199),
(51812, 'Daniel 6:11', 'Daniel', 6, 11, 'نو بيا دا کسان په يو ځائ لاړل او دانيال يې وليدلو چې دُعا يې کوله او د خپل خُدائ پاک نه يې مدد غوښتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_11.mp3', '', 1761754199, 1761754199),
(51813, 'Daniel 6:12', 'Daniel', 6, 12, 'نو بيا هغوئ بادشاه له لاړل او هغۀ ته يې د هغه شاهى حکم په حقله ياداشت ورکړو، ”آيا تاسو دا حکم نۀ وُو جارى کړے چې په راتلونکو دېرشو ورځو کښې هر چا هم بغېر ستا نه اے بادشاه سلامت، د بل معبود او يا انسان عبادت وکړو او يا دُعا يې ترينه وغوښتله هغه به د زمرو په غار کښې واچولے شى؟“ بادشاه ورته جواب ورکړو چې، ”آو، بلکل دا حکم د ميديانو او فارسيانو د قانون په مطابق دے کوم چې نۀ شى بدلېدلے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_12.mp3', '', 1761754199, 1761754199),
(51814, 'Daniel 6:13', 'Daniel', 6, 13, 'بيا هغوئ بادشاه ته ووئيل چې، ”دانيال څوک چې يو د يهوداه د جلاوطنو کسانو نه دے، هغه نه ستا پرواه ساتى، اے بادشاه سلامت او نه ستا حکم ته څۀ توجو ورکوى. هغه اوس هم په ورځ کښې درې ځله د خپل خُدائ پاک نه دُعا غواړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_13.mp3', '', 1761754199, 1761754199),
(51815, 'Daniel 6:14', 'Daniel', 6, 14, 'نو کله چې بادشاه دا خبره واورېده، نو هغه ډېر زيات خفه شو. هغۀ دا اراده وکړه چې دانيال بچ کړى او هغۀ ټوله ورځ تر نمر پرېوتو پورې د داسې لارې چارې پېدا کولو کوشش وکړو چې دانيال بچ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_14.mp3', '', 1761754199, 1761754199),
(51816, 'Daniel 6:15', 'Daniel', 6, 15, 'نو بيا هغه کسان په ډله بادشاه له ورغلل او هغۀ ته يې ووئيل، ”بادشاه سلامت، دا خبره ياد ساته چې، د ميديانو او فارسيانو د قانون په مطابق کوم يو قانون او فرمان چې بادشاه جارى کړى نو هغه بدلېدے نۀ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_15.mp3', '', 1761754199, 1761754199),
(51817, 'Daniel 6:16', 'Daniel', 6, 16, 'نو بيا بادشاه حکم وکړو، او هغوئ دانيال راوستلو او هغه يې د زمرو په غار کښې وروغورزولو. بادشاه دانيال ته ووئيل چې، ”ستا خُدائ پاک د کوم چې تۀ په وفادارۍ خِدمت کوې، هغه دې تا له خلاصون درکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_16.mp3', '', 1761754199, 1761754199),
(51818, 'Daniel 6:17', 'Daniel', 6, 17, 'يو ګټ راوړلے شو او د غار په خولۀ کېښودے شو، او بادشاه پرې خپل مهر او د خپلو حاکمانو مهرونه يې پرې ولګول، د دې دپاره چې څوک دانيال بچ نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_17.mp3', '', 1761754199, 1761754199),
(51819, 'Daniel 6:18', 'Daniel', 6, 18, 'نو بيا بادشاه خپل شاهى محل ته واپس شو او هغه شپه يې بې د خوراکه او د هر قسمه عېش عشرت نه بغېر تيره کړه. او هغه ټوله شپه ويښ وو او خوب نۀ ورتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_18.mp3', '', 1761754199, 1761754199),
(51820, 'Daniel 6:19', 'Daniel', 6, 19, 'خو په توره خړه بادشاه پاڅېدو او د زمرو غار ته په تېزۍ سره ورغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_19.mp3', '', 1761754199, 1761754199),
(51821, 'Daniel 6:20', 'Daniel', 6, 20, 'نو کله چې هغه غار ته نزدې ورورسېدو، نو هغۀ دانيال ته په غمژن آواز سره آواز ورکړو، ”اے دانياله، د ژوندى خُدائ خِدمت کوونکيه، ولې ستا خُدائ پاک د چا چې تۀ په وفادارۍ سره عبادت کوې، هغۀ دا وکړے شو چې تا د زمرو نه بچ کړى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_20.mp3', '', 1761754199, 1761754199),
(51822, 'Daniel 6:21', 'Daniel', 6, 21, 'دانيال ورله جواب ورکړو، ”بادشاه سلامت، تۀ دې د تل دپاره ژوندے اوسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_21.mp3', '', 1761754199, 1761754199),
(51823, 'Daniel 6:22', 'Daniel', 6, 22, 'زما خُدائ پاک خپله فرښته راولېږله او هغې د زمرو خولې بندې کړې. هغوئ ما ته هيڅ قسمه نقصان نۀ دے رارسولے، ځکه چې زۀ هغۀ ته بې‌ګناه ثابت شوم. بادشاه سلامت، نۀ ما ستا خلاف څۀ جرم کړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_22.mp3', '', 1761754199, 1761754199),
(51824, 'Daniel 6:23', 'Daniel', 6, 23, 'بادشاه په دې بې‌حده خوشحاله شو او حکم يې وکړو چې دانيال د غار نه راوباسئ. او کله چې يې دانيال رابهر کړو، نو په هغۀ يو زخم هم نۀ وو، ځکه چې د هغۀ په خپل خُدائ پاک باور وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_23.mp3', '', 1761754199, 1761754199),
(51825, 'Daniel 6:24', 'Daniel', 6, 24, 'بيا د بادشاه په حکم، هغه سړى راوستلے شول چا چې په دانيال د بد نيت نه اِلزام لګولے وو او د زمرو په غار کښې يې د ښځو او بچو سره وروغورزول. د غار بېخ ته د رسېدو نه وړاندې زمرو په هغوئ حمله وکړه او هډُوکى يې ورله ټوټه ټوټه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_24.mp3', '', 1761754199, 1761754199),
(51826, 'Daniel 6:25', 'Daniel', 6, 25, 'نو بيا په ټول مُلک کښې داريوس بادشاه ټولو خلقو، قومونو، او د دُنيا د هرې ژبې ويوونکو ته دا وليکل، ”په تاسو دې سلامتيا او برکت وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_25.mp3', '', 1761754199, 1761754199),
(51827, 'Daniel 6:26', 'Daniel', 6, 26, 'زۀ د خپلې بادشاهۍ په هر ځائ کښې خلقو ته دا فرمان جارى کوم چې تاسو ټول د دانيال د خُدائ نه يرېږئ او د هغۀ عزت کوئ. ځکه چې هغه ژوندے خُدائ پاک دے، او همېشه پاتې کېدونکے دے، د هغۀ بادشاهى به هيڅکله نۀ تباه کيږى، او د هغۀ بادشاهى به کله هم نۀ ختميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_26.mp3', '', 1761754199, 1761754199),
(51828, 'Daniel 6:27', 'Daniel', 6, 27, 'هغه بچ کوونکے او ساتونکے دے، هغه په آسمان او زمکه کښې نښې او عجائب څرګندوى. هغۀ دانيال د زمرو د پنجو نه بچ کړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_27.mp3', '', 1761754199, 1761754199),
(51829, 'Daniel 6:28', 'Daniel', 6, 28, 'نو دانيال د داريوس بادشاه په حکومت کښې او د فارس د بادشاه خورس په حکومت کښې ډېر مخکښې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_28.mp3', '', 1761754199, 1761754199),
(51830, 'Jeremiah 32:1', 'Jeremiah', 32, 1, 'د يهوداه د مُلک د صدقياه بادشاه د بادشاهۍ په لسم کال کوم چې اتلسم کال د نبوکدنضر د بادشاهۍ وو، د مالِک خُدائ کلام يرمياه ته ورکړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_1.mp3', '', 1761754199, 1761754199),
(51831, 'Jeremiah 32:2', 'Jeremiah', 32, 2, 'په هغه وخت کښې چې د بابل د بادشاه لښکرو د يروشلم نه ګېره اچولې وه نو يرمياه په دې ورځو کښې د يهوداه د شاهى محل دننه په فوجى چاوڼۍ کښې بند وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_2.mp3', '', 1761754199, 1761754199),
(51832, 'Jeremiah 32:3', 'Jeremiah', 32, 3, 'نو صدقياه بادشاه هغه هلته قېد کړو او ورته يې ووئيل چې، ”تۀ ولې دا پېشګوئې کوې؟ چې مالِک خُدائ فرمائى چې زۀ دا ښار د بابل بادشاه ته حواله کوم نو بيا به هغه په دې ښار قبضه وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_3.mp3', '', 1761754199, 1761754199),
(51833, 'Jeremiah 32:4', 'Jeremiah', 32, 4, 'صدقياه بادشاه به د بابليانو د لاس نه ونۀ تښتى، او هغه به په يقين سره د بابل بادشاه ته حواله کړے شى، او هغه به دۀ سره مخامخ خبرې وکړى او دے به يې په خپلو سترګو سره وګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_4.mp3', '', 1761754199, 1761754199),
(51834, 'Jeremiah 32:5', 'Jeremiah', 32, 5, 'هغه به صدقياه بابل ته بوځى او هغه به تر هغې پورې هلته پاتې وى چې ترڅو مې ورسره خپل عمل نۀ وى کړے، مالِک خُدائ فرمائى. کۀ چرې تۀ د بابليانو خلاف جنګ وکړې، نو تۀ به کامياب نۀ شې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_5.mp3', '', 1761754199, 1761754199),
(51835, 'Jeremiah 32:6', 'Jeremiah', 32, 6, 'يرمياه وفرمائيل چې، ”نو په دغه وخت کښې د مالِک خُدائ کلام په ما نازل شو چې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_6.mp3', '', 1761754199, 1761754199),
(51836, 'Jeremiah 32:7', 'Jeremiah', 32, 7, 'ستا د ترۀ زوئ حنم‌ايل د سلوم زوئ به تا له راشى او درته به وائى چې په عنتوت کښې زما زمکه واخله، ځکه چې تۀ زما نزدې خپلوان يې نو اول د اخستو حق ستا دے او دا ستا فرض هم جوړيږى چې تۀ يې واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_7.mp3', '', 1761754199, 1761754199),
(51837, 'Jeremiah 32:8', 'Jeremiah', 32, 8, 'نو بيا لکه څنګه چې مالِک خُدائ فرمائيلى وُو، زما د ترۀ زوئ حنم‌ايل فوجى چاوڼۍ ته راغلو او هغۀ ووئيل چې په عنتوت کښې زما زمکه واخله کومه چې د بنيامين په علاقه کښې ده. ځکه چې دا ستا حق دے چې تۀ يې خلاصه کړې او د خپل ځان دپاره يې واخلې. نو زۀ په دې پوهه شوم چې مالِک خُدائ ما سره په هم دې حقله خبره کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_8.mp3', '', 1761754199, 1761754199),
(51838, 'Jeremiah 32:9', 'Jeremiah', 32, 9, 'نو بيا ما هغه زمکه د ترۀ زوئ حنم‌ايل نه د اوولسو سپينو زرو سيکو په بيعه واخستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_9.mp3', '', 1761754199, 1761754199),
(51839, 'Jeremiah 32:10', 'Jeremiah', 32, 10, 'ما د ګواهانو په وړاندې د هغه زمکې انتقال نامه وليکله او په هغې مې دستخط وکړو او مهر مې پرې ولګولو او هغه سپين زر مې په تله کښې وتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_10.mp3', '', 1761754199, 1761754199),
(51840, 'Jeremiah 32:11', 'Jeremiah', 32, 11, 'بيا ما د مهر شوې انتقال نامې چې د خرڅولو ټول اصُول او شرائط په کښې درج شوى وُو او هم يوه غېر مهر شوې کاپې راواخسته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_11.mp3', '', 1761754199, 1761754199),
(51841, 'Jeremiah 32:12', 'Jeremiah', 32, 12, 'او دواړه مې باروک د نيرياه زوئ او د محسياه نمسى ته د حنم‌ايل او د هغه ګواهانو چا چې په انتقال دستخط کړے وو او د هغه ټولو خلقو په موجودګۍ کښې چې په فوجى چاوڼۍ کښې ناست وُو حواله کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_12.mp3', '', 1761754199, 1761754199),
(51842, 'Jeremiah 32:13', 'Jeremiah', 32, 13, 'د هغه ټولو کسانو په مخکښې ما باروک ته هدايت ورکړو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_13.mp3', '', 1761754199, 1761754199),
(51843, 'Jeremiah 32:14', 'Jeremiah', 32, 14, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، د سودا دا دواړه کاغذونه واخله چې په يو باندې مهر شته او په بل نشته او دواړه په خاورين منګى کښې واچوه ترڅو چې د ډېر وخت دپاره محفوظ پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_14.mp3', '', 1761754199, 1761754199),
(51844, 'Jeremiah 32:15', 'Jeremiah', 32, 15, 'نو مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، په دې مُلک کښې به بيا کورونه، پټى او د انګورو باغونه اخستل کيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_15.mp3', '', 1761754199, 1761754199),
(51845, 'Jeremiah 32:16', 'Jeremiah', 32, 16, '”د هغې نه وروستو کله چې ما د زمکې کاغذونه باروک د نيرياه زوئ له ورکړل نو بيا ما دُعا وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_16.mp3', '', 1761754199, 1761754199),
(51846, 'Jeremiah 32:17', 'Jeremiah', 32, 17, 'اے مالِکه قادر مطلق خُدايه، تا په خپل لوئ طاقت او قُدرت سره او په خپل زورَور لاس سره آسمان او زمکه جوړ کړل. ستا دپاره يو کار هم ناممکن نۀ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_17.mp3', '', 1761754199, 1761754199),
(51847, 'Jeremiah 32:18', 'Jeremiah', 32, 18, 'تۀ زرګونو خلقو سره مينه کوې، خو د مور پلار د ګناهونو په وجه تۀ د هغوئ بچو له سزا ورکوې. اے عظيم او طاقتور خُدايه، د چا نوم چې مالِک خُدائ ربُ الافواج دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_18.mp3', '', 1761754199, 1761754199),
(51848, 'Jeremiah 32:19', 'Jeremiah', 32, 19, 'ستا مقصد عظيم او ستا کارونه زورَور دى. ستا سترګې د انسان ټولې لارې وينى، او تۀ هر يو ته د خپل چال چلن او عمل په مطابق اجر ورکوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_19.mp3', '', 1761754199, 1761754199),
(51849, 'Jeremiah 32:20', 'Jeremiah', 32, 20, 'تا په مِصر کښې معجزې او حېرانونکى کارونه کړى دى، او ستا دا سلسله په بنى اِسرائيلو او په ټولو انسانانو کښې تر ننه پورې راروانه ده، او تر نن ورځ پورې تا خپل نوم ته جلال ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_20.mp3', '', 1761754199, 1761754199),
(51850, 'Jeremiah 32:21', 'Jeremiah', 32, 21, 'تا په خپل زورَور لاس، لوئ دهشت، عجيبه کارونو او معجزو سره خپل خلق بنى اِسرائيل د مِصر نه راوويستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_21.mp3', '', 1761754199, 1761754199),
(51851, 'Jeremiah 32:22', 'Jeremiah', 32, 22, 'تا هغوئ ته هغه زرخيزه زمکه ورکړه د کومې دې چې د هغوئ د پلار نيکۀ سره وړاندې وعده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_22.mp3', '', 1761754199, 1761754199),
(51852, 'Jeremiah 32:23', 'Jeremiah', 32, 23, 'خو چې کله زمونږ پلار نيکۀ په دې مُلک کښې داخل شول او په دې يې قبضه وکړه نو هغوئ نۀ ستا واورېدل او نۀ يې ستا د شريعت پيروى وکړه. او هغوئ په هغه څۀ باندې عمل ونۀ کړو د کوم چې ورله تا حکم کړے وو. نو بيا ځکه تا دا ټول افتونه په هغوئ رانازل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_23.mp3', '', 1761754199, 1761754199),
(51853, 'Jeremiah 32:24', 'Jeremiah', 32, 24, 'وګورئ چې بابليانو د ښار د نيولو دپاره ګېرچاپېره څنګه د خاورو ډېرى جوړ کړل. د جنګ، قحط او وبا په وجه به دا ښار بابليانو ته څوک چې پرې حمله کوى حواله شى. تا چې څۀ وئيلى وُو نو هغه کارونه وشول، اوس يې په خپله وګوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_24.mp3', '', 1761754199, 1761754199),
(51854, 'Jeremiah 32:25', 'Jeremiah', 32, 25, 'خو اے مالِکه خُدايه زما ربه تۀ هغه ذات يې چې ما ته دې حُکم راکړو چې د ګواهانو په مخکښې هغه زمکه واخله، سره د دې چې د ښار حالت داسې خراب وو چې بابليانو نيولو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_25.mp3', '', 1761754199, 1761754199),
(51855, 'Jeremiah 32:26', 'Jeremiah', 32, 26, 'نو بيا د مالِک خُدائ له طرفه دا پېغام يرمياه ته راغلو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_26.mp3', '', 1761754199, 1761754199),
(51856, 'Jeremiah 32:27', 'Jeremiah', 32, 27, '”زۀ مالِک قادر مطلق خُدائ يم، او د ټولو مخلوقاتو رب العالمين يم. آيا داسې کار شته چې د هغې کول زما دپاره ناممکن وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_27.mp3', '', 1761754199, 1761754199),
(51857, 'Jeremiah 32:28', 'Jeremiah', 32, 28, 'نو ځکه زۀ دا ښار د بابل بادشاه نبوکدنضر او د هغۀ لښکر ته حواله کوم، نو هغوئ به دا قبضه کړى', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_28.mp3', '', 1761754199, 1761754199),
(51858, 'Jeremiah 32:29', 'Jeremiah', 32, 29, 'او د دېوال نه اخوا بابليان به راشى او په دې ښار به اور بل کړى. هغوئ به ټول کورونه وسوزوى، چرته چې خلقو زۀ په دې غصه کړم چې د کوټو په چتونو يې بعل ته خوشبويۍ وسوزولې او نورو معبودانو ته يې د څښلو نذرانې پېش کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_29.mp3', '', 1761754199, 1761754199),
(51859, 'Jeremiah 32:30', 'Jeremiah', 32, 30, 'نو د اِسرائيل او د يهوداه خلقو د ځوانۍ نه واخله تر اوسه پورې د شرارت نه بغېر بل کوم کار نۀ دے کړے او هر وخت يې زۀ په خپل کردار سره غصه کړے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_30.mp3', '', 1761754199, 1761754199),
(51860, 'Jeremiah 32:31', 'Jeremiah', 32, 31, 'د کومې ورځې نه چې دا ښار جوړ شوے دے نو د هغې ورځې نه تر ننه پورې زۀ دې خلقو غصه کړے او په قهر کړے يم. نو ځکه زۀ دا ښار د خپل مخ نه اخوا کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_31.mp3', '', 1761754199, 1761754199),
(51861, 'Jeremiah 32:32', 'Jeremiah', 32, 32, 'د اِسرائيل او د يهوداه خلقو زۀ په هغه ټولو شرارتونو کوم چې دوئ وکړل غصه کړم کۀ هغه بادشاهانو، آفسرانو، مشرانو، اِمامانو او کۀ نبيانو هم کړى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_32.mp3', '', 1761754199, 1761754199),
(51862, 'Jeremiah 32:33', 'Jeremiah', 32, 33, 'زما خلقو ما ته شا کړې ده، او ما ته د کتلو نه يې اِنکار کړے دے، سره د دې چې ما بار بار په نرمۍ سره هغوئ ته تعليم ورکړے دے، خو هغوئ زما خبرو ته غوږ نۀ دے نيولے او نۀ يې زما اصلاح قبوله کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_33.mp3', '', 1761754199, 1761754199),
(51863, 'Jeremiah 32:34', 'Jeremiah', 32, 34, 'هغوئ خپل حرام بُتان زما په کور کښې اېښى دى، کوم کور چې زما د عبادت دپاره جوړ شوے وو او هغوئ په دې زما کور پليت کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_34.mp3', '', 1761754199, 1761754199),
(51864, 'Jeremiah 32:35', 'Jeremiah', 32, 35, 'هغوئ د هنوم په وادۍ کښې بعل ته علاقائى عبادتخانې د دې دپاره جوړې کړې چې مولک بُت ته خپل زامن او لوڼه قربانى کړى. نۀ خو ما هغوئ له د داسې کولو حُکم ورکړو او نۀ زما ذهن ته داسې خرابه خبره راغلې ده چې هغوئ به داسې په بد او پليت کار کولو سره يهوداه ګناه ګار کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_35.mp3', '', 1761754199, 1761754199),
(51865, 'Jeremiah 32:36', 'Jeremiah', 32, 36, '”تاسو وايئ چې، دا ښار به د جنګ، قحط، او وبا په وجه د بابل بادشاه قبضه کړى، خو مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د دې ښار په حقله فرمائى چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_36.mp3', '', 1761754199, 1761754199),
(51866, 'Jeremiah 32:37', 'Jeremiah', 32, 37, 'زۀ به په يقين سره خپل غوره شوى خلق د ټولو مُلکونو نه واپس دې ځائ ته راولم کوم چې ما د خپلې غصې او لوئ غضب په وخت کښې خوارۀ وارۀ کړى وُو. او هغوئ به واپس راولم او په دې ځائ کښې به نور په امن او سکون سره اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_37.mp3', '', 1761754199, 1761754199),
(51867, 'Jeremiah 32:38', 'Jeremiah', 32, 38, 'بيا به هغوئ زما خلق وى او زۀ به د هغوئ خُدائ پاک يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_38.mp3', '', 1761754199, 1761754199),
(51868, 'Jeremiah 32:39', 'Jeremiah', 32, 39, 'زۀ به هغوئ ته د زړۀ او د سوچ يووالے ورکړم چې د خپل ځان د خوشحالۍ او د خپل نسل د آبادۍ او سکون دپاره به زما نه همېشه يريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_39.mp3', '', 1761754199, 1761754199),
(51869, 'Jeremiah 32:40', 'Jeremiah', 32, 40, 'زۀ به د هغوئ سره ابدى لوظ وکړم، چې زۀ به د هغوئ سره ښېګړه کول هيڅکله نۀ پرېږدم. او زۀ به خپله يره د هغوئ په زړُونو کښې واچوم، ترڅو چې نور هغوئ ما نه لرې لاړ نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_40.mp3', '', 1761754199, 1761754199),
(51870, 'Jeremiah 32:41', 'Jeremiah', 32, 41, 'هغوئ ته په برکت ورکولو سره ما ته خوشحالى ملاويږى، او زۀ به په وفادارۍ او پوره زړۀ سره هغوئ په دې مُلک کښې دوباره آباد کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_41.mp3', '', 1761754199, 1761754199),
(51871, 'Jeremiah 32:42', 'Jeremiah', 32, 42, 'لکه څنګه چې ما په دې خلقو دا لوئ افت راوستو، نو دغه شان به زۀ دوئ ته هغه ټولې سوکالۍ هم ورکړم د کومې چې ما هغوئ سره وعده کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_42.mp3', '', 1761754199, 1761754199),
(51872, 'Jeremiah 32:43', 'Jeremiah', 32, 43, 'نو يو ځل به بيا په دې مُلک کښې زمکې واخستلے شى، د کوم چې تاسو وايئ چې دا خو صحرا او بې‌کاره زمکه ده، بغېر د انسانانو او ځناورو، ځکه چې دا خو بابليانو ته په قبضه کښې ورکړے شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_43.mp3', '', 1761754199, 1761754199),
(51873, 'Jeremiah 32:44', 'Jeremiah', 32, 44, 'آو، د بنيامين په علاقه، د يروشلم په خوا او شا، د يهوداه په ښارونو، غريزه علاقو، د غرونو په کلو، مغربى صحراګانو او په نجب کښې به زمکې د سپينو زرو سيکو باندې اخستلے کيږى او مهر شوى انتقالونه او ګواهان به په کښې نيولے کيږى، ځکه چې زۀ به دا قوم د غلامۍ نه واپس راولم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah32_verse_44.mp3', '', 1761754199, 1761754199),
(51874, 'Zechariah 2:1', 'Zechariah', 2, 1, 'بيا ما بره وکتل، او هلته زما په وړاندې د ناپ تول فيته په لاس يو سړے ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_1.mp3', '', 1761754199, 1761754199),
(51875, 'Zechariah 2:2', 'Zechariah', 2, 2, 'نو ما ترې نه تپوس وکړو چې، ”تۀ چرته روان يې؟“ هغۀ راته په جواب کښې وفرمائيل، ”د يروشلم ناپ کولو له، چې دا معلوم کړم چې هغه څومره پلن او څومره اوږد دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_2.mp3', '', 1761754199, 1761754199),
(51876, 'Zechariah 2:3', 'Zechariah', 2, 3, 'نو څۀ وخت چې کومې فرښتې ما سره خبرې کولې هغه مخکښې لاړه نو په دې وخت کښې يوه بله فرښته د هغې سره مِلاوېدو دپاره راغله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_3.mp3', '', 1761754199, 1761754199),
(51877, 'Zechariah 2:4', 'Zechariah', 2, 4, 'او هغې ته يې وفرمائيل، ”په منډه لاړ شه، هغه ځوان سړى ته ووايه چې يروشلم به د دېوالونو نه بغېر ښار وى ځکه چې دې کښې به انسانان او ځناور په ډېر لوئ تعداد وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_4.mp3', '', 1761754199, 1761754199),
(51878, 'Zechariah 2:5', 'Zechariah', 2, 5, 'او زۀ به په خپله د دې نه ګېرچاپېره د اور دېوال يم، مالِک خُدائ فرمائى، او زۀ به په خپله د دې ښار په مينځ کښې جلال يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_5.mp3', '', 1761754199, 1761754199),
(51879, 'Zechariah 2:6', 'Zechariah', 2, 6, '”راشئ، راشئ. د شمالى مُلک د جلاوطنۍ نه راوتښتئ،“ مالِک خُدائ فرمائى، ”ځکه ما تاسو په ټوله دُنيا کښې څلور واړو طرفونو ته خوارۀ کړئ،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_6.mp3', '', 1761754199, 1761754199),
(51880, 'Zechariah 2:7', 'Zechariah', 2, 7, '”اے د صيون خلقو راوتښتئ، څوک چې په بابل کښې جلاوطن شوى يئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_7.mp3', '', 1761754199, 1761754199),
(51881, 'Zechariah 2:8', 'Zechariah', 2, 8, 'نو مالِک خُدائ ربُ الافواج داسې فرمائى، ”زۀ هغه جلالى خُدائ هغه قومونو ته راولېږلم، چا چې تۀ لوټ کړے يې، ځکه چې هر څوک چې تا سره ولګى نو هغه د خپلې سترګې ګاټى سره لګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_8.mp3', '', 1761754199, 1761754199),
(51882, 'Zechariah 2:9', 'Zechariah', 2, 9, 'په يقين سره به زۀ خپل لاس د هغوئ خلاف راوچت کړم نو د هغوئ غلامان به هغوئ لوټ کړى. بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ ربُ الافواج رالېږلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_9.mp3', '', 1761754199, 1761754199),
(51883, 'Zechariah 2:10', 'Zechariah', 2, 10, 'چغې ووهه او خوشحالى وکړه، اے صيون لورې. ځکه چې زۀ راروان يم، او زۀ به ستاسو په مينځ کښې اوسېږم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_10.mp3', '', 1761754199, 1761754199),
(51884, 'Zechariah 2:11', 'Zechariah', 2, 11, '”په هغه ورځ به ډېر قومونه د مالِک خُدائ سره يوځائ شى او هغوئ به زما خلق شى. زۀ به ستاسو په مينځ کښې اوسېږم او تاسو به په دې پوهه شئ چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_11.mp3', '', 1761754199, 1761754199),
(51885, 'Zechariah 2:12', 'Zechariah', 2, 12, 'مالِک خُدائ به په مقدسه زمکه کښې يهوداه لکه د خپلې حصې ميراث حاصل کړى او يروشلم به بيا لکه د خپل ښار غوره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_12.mp3', '', 1761754199, 1761754199),
(51886, 'Zechariah 2:13', 'Zechariah', 2, 13, 'اے ټولو انسانانو د مالِک خُدائ په وړاندې خاموش ودرېږئ، ځکه چې هغه په خپله د خپل مقدس ځائ نه راوچت شوے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah2_verse_13.mp3', '', 1761754199, 1761754199),
(51887, 'Ezra 4:1', 'Ezra', 4, 1, 'کله چې د یهودا او بنیامین د خلکو دښمنانو واورېدل چې هغه خلک چې له جلاوطنۍ څخه راستانه شوي دي د اسراییلو د څښتن خدای د عبادت ځای بیا جوړوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_1.mp3', '', 1761754199, 1761754199),
(51888, 'Ezra 4:2', 'Ezra', 4, 2, 'نو هغوی زروبابل او د طایفو مشرانو ته ورغلل او هغوی ته یې وویل: «مونږ ته اجازه راکړئ چې ستاسو سره مرسته وکړو! له هغه وخت راهیسې چې د آشور پاچا اسرحدون مونږ دلته راوستلي یو، مونږ ستاسو په شان ستاسو د خدای عبادت کوو او هغه ته قربانۍ وړاندې کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_2.mp3', '', 1761754199, 1761754199),
(51889, 'Ezra 4:3', 'Ezra', 4, 3, 'زروبابل، یشوع او د طایفو نورو مشرانو هغوی ته وویل: «مونږ خپل خدای ته د کور په جوړولو کې ستاسو مرستې ته هېڅ اړتیا نه لرو، خو مونږ به خپله هغه خپل څښتن، یعنې د اسراییلو خدای ته جوړ کړو لکه څنګه چې د فارس پاچا کوروش امر کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_3.mp3', '', 1761754199, 1761754199),
(51890, 'Ezra 4:4', 'Ezra', 4, 4, 'نو هغو خلکو چې په دې وطن کې اوسېدل هڅه وکړه چې د یهودیانو زړونه تور کړي، هغوی ووېروي او مجبور یې کړي چې د ودانولو کار ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_4.mp3', '', 1761754199, 1761754199),
(51891, 'Ezra 4:5', 'Ezra', 4, 5, 'همدارنګه هغوی د فارس حکومتي مامورینو ته رشوت هم ورکاوه چې د هغوی په خلاف کار وکړي. هغوی دې کار ته د کوروش د پاچاهۍ په دوران کې او حتی د داریوش د پاچاهۍ تر پیل کېدلو پورې دوام ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_5.mp3', '', 1761754199, 1761754199),
(51892, 'Ezra 4:6', 'Ezra', 4, 6, 'د خشایار پاچا د امپراتورۍ په پیل کې د یهودا او اورشلیم د خلکو دښمنانو په هغوی باندې لیکل شوي تورونه ولګول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_6.mp3', '', 1761754199, 1761754199),
(51893, 'Ezra 4:7', 'Ezra', 4, 7, 'د فارس د پاچا ارتخششتا د امپراتورۍ په وخت کې بشلام، میتردات، تبییل او د هغوی ملګرو پاچا ته لیک ولیکه. دا لیک په آرامي ژبه لیکل شوی ؤ چې د لوستلو په وخت کې به ترجمه کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_7.mp3', '', 1761754199, 1761754199),
(51894, 'Ezra 4:8', 'Ezra', 4, 8, 'همدارنګه رحوم والي او د ولایت منشي شمشای د اورشلیم په اړه دا لاندې لیک ارتخششتا پاچا ته ولیکه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_8.mp3', '', 1761754199, 1761754199),
(51895, 'Ezra 4:9', 'Ezra', 4, 9, '«د والي رحوم، د منشي شمشای، د هغوی د ملګرو، قاضیانو او نورو ټولو مامورینو او څارونکو له خوا چې په اصل کې له ارک، بابل او د عیلام د شوشه څخه دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_9.mp3', '', 1761754199, 1761754199),
(51896, 'Ezra 4:10', 'Ezra', 4, 10, 'د هغو نورو خلکو سره یوځای چې لوی او عزتمن آشور بانیپال د خپلو هېوادونو څخه شړلي وو او د سامرې په ښار او د فرات د سیند د لوېدیځې خوا ولایت په نورو برخو کې یې ځای په ځای کړي وو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_10.mp3', '', 1761754199, 1761754199),
(51897, 'Ezra 4:11', 'Ezra', 4, 11, 'د لیک متن دا دی: «ارتخششتا پاچا ته د هغه د هغو خدمتګارانو له خوا چې د فرات د سیند په لوېدیځې خوا ولایت کې اوسیږي سلامونه وړاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_11.mp3', '', 1761754199, 1761754199),
(51898, 'Ezra 4:12', 'Ezra', 4, 12, 'مونږ غواړو چې تاسو اعلیحضرت په دې خبر شئ چې هغه یهودیان چې ستاسو د نورو سیمو څخه دلته راغلي دي، په اورشلیم کې ځای په ځای شوي دي او هغه بد او یاغي ښار بېرته ودانوي. نژدې دی چې هغوی د دېوالونو او بنیادونو بیا جوړونه پای ته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_12.mp3', '', 1761754199, 1761754199),
(51899, 'Ezra 4:13', 'Ezra', 4, 13, 'ای اعلیحضرته، که چېرې دا ښار بېرته ودان شو او د هغه دېوالونه جوړ شول، نو خلک به د باج او مالیې ورکول بس کړي او ستاسو شاهي عایدات به لږ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_13.mp3', '', 1761754199, 1761754199),
(51900, 'Ezra 4:14', 'Ezra', 4, 14, 'نو څرنګه چې مونږ تاسو اعلیحضرت ته وفادار یو، مونږ نه غواړو چې ستاسو بې عزتي وشي، نو مونږ دا وړاندیز کوو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_14.mp3', '', 1761754199, 1761754199),
(51901, 'Ezra 4:15', 'Ezra', 4, 15, 'تاسو امر وکړئ چې د پخوانیو پاچاهانو سندونه دې ولټول شي. که تاسو دا کار وکړئ، نو تاسو ته به څرګنده شي چې دا ښار تل یاغي ؤ او د پخوا زمانو څخه یې پاچاهان او والیان کړولي دي. د دې ښار په خلکو باندې حکومت کول تل سخت وو. نو ځکه دا ښار وران شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_15.mp3', '', 1761754199, 1761754199),
(51902, 'Ezra 4:16', 'Ezra', 4, 16, 'له دې امله مونږ په دې باندې باور لرو چې که چېرې دا ښار بیا ودان شو او د هغه دېوالونه جوړ شول، نو تاسو اعلیحضرت به ونه شئ کولای چې د فرات د سیند د لوېدیځې خوا ولایت باندې خپله واکمني وساتئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_16.mp3', '', 1761754199, 1761754199),
(51903, 'Ezra 4:17', 'Ezra', 4, 17, 'پاچا داسې ځواب ورولېږه: «د رحوم والي، د ولایت منشي شمشای او د هغوی ملګرو ته چې په سامره او د فرات د سیند د لوېدیځې خوا ولایت په نورو برخو کې اوسیږي، په تاسو دې سلام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_17.mp3', '', 1761754199, 1761754199),
(51904, 'Ezra 4:18', 'Ezra', 4, 18, 'هغه لیک چې تاسو رالېږلی ؤ وروسته له ترجمې څخه ماته ولوستل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_18.mp3', '', 1761754199, 1761754199),
(51905, 'Ezra 4:19', 'Ezra', 4, 19, 'ما امر کړی ؤ او څېړنه وشوه او په رښتیا دا څرګنده شوه چې اورشلیم له پخوا زمانو راهیسې د شاهي واکمنۍ په خلاف راپورته شوی او هغه ښار د یاغیانو او باغیانو ډک ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_19.mp3', '', 1761754199, 1761754199),
(51906, 'Ezra 4:20', 'Ezra', 4, 20, 'قدرتمندو پاچاهانو هلته پاچاهي کړې ده او د فرات د سیند له لوېدیځې خوا په ټول ولایت باندې یې حکومت کړی، باج او مالیه یې راټوله کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_20.mp3', '', 1761754199, 1761754199),
(51907, 'Ezra 4:21', 'Ezra', 4, 21, 'نو له دې امله تاسو باید حکم جاري کړئ چې زما د بل حکم پورې هغه خلک د ښار د بیا ودانولو کار ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_21.mp3', '', 1761754199, 1761754199),
(51908, 'Ezra 4:22', 'Ezra', 4, 22, 'لټي ونه کړئ او دا کار همدا اوس وکړئ، ترڅو امپراتورۍ ته نور زیان ونه رسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_22.mp3', '', 1761754199, 1761754199),
(51909, 'Ezra 4:23', 'Ezra', 4, 23, 'څنګه چې د ارتخششتا پاچا لیک رحوم، شمشای او د هغو ملګرو ته ولوستل شو، هغوی په بیړه اورشلیم ته لاړل او یهودیان یې په زوره مجبور کړل چې د ښار بیا ودانول ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_23.mp3', '', 1761754199, 1761754199),
(51910, 'Ezra 4:24', 'Ezra', 4, 24, 'په دې ډول په اورشلیم کې د خدای د کور د جوړولو کار درېدلی ؤ او د فارس پاچا داریوش د امپراتورۍ تر دوهم کال پورې وځنډېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra4_verse_24.mp3', '', 1761754199, 1761754199);